deleted = 0
AND id = #{p.id}
AND ( project_name LIKE CONCAT('%', #{p.keyword}, '%') OR title LIKE CONCAT('%', #{p.keyword}, '%') OR keywords LIKE CONCAT('%', #{p.keyword}, '%') )
AND 1 = 0
AND province = #{p.provinceList[0]}
AND (
province = #{pItem}
)
ORDER BY id = #{p.id} DESC publish_time DESC LIMIT 1

